#!/usr/bin/env python3
"""Generate remaining 5 tools: lottery-generator, yes-no, flip-text, bubble-text, bold-text-generator"""
import os, sys
sys.path.insert(0, '/home/chison/tools-site/scripts')
from gen_tools import make_page

BASE = '/home/chison/tools-site'

def gen(slug, **kw):
    js_cn = kw.pop('js_cn', kw.get('js',''))
    js_en = kw.pop('js_en', kw.get('js',''))
    cn_empty = kw.pop('cn_empty','')
    cn_copied = kw.pop('cn_copied','')
    en_empty = kw.pop('en_empty','')
    en_copied = kw.pop('en_copied','')
    
    cn = make_page(slug, lang='cn', js='', **kw)
    en = make_page(slug, lang='en', js='', **kw)
    
    js_cn = js_cn.replace('EMPTY', cn_empty).replace('COPIED', cn_copied)
    js_en = js_en.replace('EMPTY', en_empty).replace('COPIED', en_copied)
    
    cn = cn.replace('</body></html>', '<script>\n' + js_cn + '\n</script>\n</body></html>')
    en = en.replace('</body></html>', '<script>\n' + js_en + '\n</script>\n</body></html>')
    
    with open(f'{BASE}/{slug}/index.html', 'w') as f: f.write(cn)
    with open(f'{BASE}/en/{slug}/index.html', 'w') as f: f.write(en)
    print(f'✅ {slug}')

# Read flip JS from file (has special unicode chars)
with open('/tmp/flip_js.txt') as f:
    flip_js = f.read().strip()

