    body_cn='<div class="tool-section"><h2>输入文字</h2><textarea id="inputText" placeholder="输入要转换的文字..." style="min-height:80px"></textarea></div>\n<div class="tool-section"><h2>选择风格</h2><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px"><button class="btn btn-primary" onclick="convertStyle(\'bold\')" id="btnBold">𝐁 粗体</button><button class="btn btn-secondary" onclick="convertStyle(\'italic\')" id="btnItalic">𝐼 斜体</button><button class="btn btn-secondary" onclick="convertStyle(\'boldItalic\')" id="btnBoldItalic">𝑩 粗斜体</button><button class="btn btn-secondary" onclick="convertStyle(\'script\')" id="btnScript">𝒮 花体</button><button class="btn btn-secondary" onclick="convertStyle(\'double\')" id="btnDouble">𝔻 双线体</button><button class="btn btn-secondary" onclick="convertStyle(\'mono\')" id="btnMono">𝙼 等宽体</button><button class="btn btn-secondary" onclick="convertStyle(\'sans\')" id="btnSans">𝗔 无衬线粗</button><button class="btn btn-secondary" onclick="convertStyle(\'sansItalic\')" id="btnSansItalic">𝘈 无衬线斜</button><button class="btn btn-secondary" onclick="convertStyle(\'sansBoldItalic\')" id="btnSansBoldItalic">𝘼 无衬线粗斜</button></div></div>\n<div class="tool-section"><h2>转换结果</h2><div class="result-output" id="resultOutput" style="font-size:1.5rem">等待输入...</div><div class="result-actions"><button class="btn btn-primary" onclick="copyResult()">📋 复制结果</button><button class="btn btn-secondary" onclick="clearAll()">🗑️ 清空</button></div></div>\n<div class="tool-section"><h2>效果预览</h2><div class="result-output" id="preview" style="font-size:1.2rem">The quick brown fox jumps over the lazy dog.</div></div>',
    body_en='<div class="tool-section"><h2>Enter Text</h2><textarea id="inputText" placeholder="Enter text to convert..." style="min-height:80px"></textarea></div>\n<div class="tool-section"><h2>Select Style</h2><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px"><button class="btn btn-primary" onclick="convertStyle(\'bold\')" id="btnBold">𝐁 Bold</button><button class="btn btn-secondary" onclick="convertStyle(\'italic\')" id="btnItalic">𝐼 Italic</button><button class="btn btn-secondary" onclick="convertStyle(\'boldItalic\')" id="btnBoldItalic">𝑩 Bold Italic</button><button class="btn btn-secondary" onclick="convertStyle(\'script\')" id="btnScript">𝒮 Script</button><button class="btn btn-secondary" onclick="convertStyle(\'double\')" id="btnDouble">𝔻 Double</button><button class="btn btn-secondary" onclick="convertStyle(\'mono\')" id="btnMono">𝙼 Mono</button><button class="btn btn-secondary" onclick="convertStyle(\'sans\')" id="btnSans">𝗔 Sans Bold</button><button class="btn btn-secondary" onclick="convertStyle(\'sansItalic\')" id="btnSansItalic">𝘈 Sans Italic</button><button class="btn btn-secondary" onclick="convertStyle(\'sansBoldItalic\')" id="btnSansBoldItalic">𝘼 Sans Bold Italic</button></div></div>\n<div class="tool-section"><h2>Result</h2><div class="result-output" id="resultOutput" style="font-size:1.5rem">Waiting for input...</div><div class="result-actions"><button class="btn btn-primary" onclick="copyResult()">📋 Copy</button><button class="btn btn-secondary" onclick="clearAll()">🗑️ Clear</button></div></div>\n<div class="tool-section"><h2>Preview</h2><div class="result-output" id="preview" style="font-size:1.2rem">The quick brown fox jumps over the lazy dog.</div></div>',
    # For bold text, use a simpler approach - just use the bold style (which uses BMP chars only)
    js_cn='var maps={bold:{A:"𝐀",B:"𝐁",C:"𝐂",D:"𝐃",E:"𝐄",F:"𝐅",G:"𝐆",H:"𝐇",I:"𝐈",J:"𝐉",K:"𝐊",L:"𝐋",M:"𝐌",N:"𝐍",O:"𝐎",P:"𝐏",Q:"𝐐",R:"𝐑",S:"𝐒",T:"𝐓",U:"𝐔",V:"𝐕",W:"𝐖",X:"𝐗",Y:"𝐘",Z:"𝐙",a:"𝐚",b:"𝐛",c:"𝐜",d:"𝐝",e:"𝐞",f:"𝐟",g:"𝐠",h:"𝐡",i:"𝐢",j:"𝐣",k:"𝐤",l:"𝐥",m:"𝐦",n:"𝐧",o:"𝐨",p:"𝐩",q:"𝐪",r:"𝐫",s:"𝐬",t:"𝐭",u:"𝐮",v:"𝐯",w:"𝐰",x:"𝐱",y:"𝐲",z:"𝐳"}}; function convertStyle(style){var input=document.getElementById("inputText").value;if(!input)return;var map=maps[style];document.getElementById("resultOutput").textContent=input.split("").map(function(c){return map[c]||c;}).join("");var preview="The quick brown fox jumps over the lazy dog.";document.getElementById("preview").textContent=preview.split("").map(function(c){return map[c]||c;}).join("");} function copyResult(){var t=document.getElementById("resultOutput").textContent;if(!t||t==="EMPTY")return;navigator.clipboard.writeText(t).then(function(){showToast("COPIED");});} function clearAll(){document.getElementById("inputText").value="";document.getElementById("resultOutput").textContent="EMPTY";} function showToast(m){var t=document.getElementById("toast");t.textContent=m;t.classList.add("show");setTimeout(function(){t.classList.remove("show");},2000);} document.getElementById("inputText").addEventListener("input",function(){convertStyle("bold");});',
